    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    directions = [(-1,0), (1,0), (0,-1), (0,1)]

    def is_valid(r, c, visited):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r,c) not in visited

    stack = [(start, [start], set([start]))]
    while stack:
        (r, c), path, visited = stack.pop()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc, visited):
                new_path = path + [(nr, nc)]
                new_visited = visited | set([(nr, nc)])
                if (nr, nc) == goal:
                    return new_path
                stack.append(((nr, nc), new_path, new_visited))
    return []
