        return []

    def neighbors(pos):
        r, c = pos
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                yield (nr, nc)

    stack = [(start, [start])]
    visited = set([start])
    bounded_stack = deque()
    max_depth = rows * cols

    while stack or bounded_stack:
        if stack:
            (r, c), path = stack.pop()
            current_depth = len(path)
            if current_depth <= max_depth:
                if (r, c) == goal:
                    return path
                for next_pos in neighbors((r, c)):
                    if next_pos not in visited:
                        visited.add(next_pos)
                        bounded_stack.append(((next_pos[0], next_pos[1]), path + [(next_pos[0], next_pos[1])]))
        elif bounded_stack and bounded_stack[0][0] == goal:
            return bounded_stack.popleft()[1]
        elif bounded_stack and len(bounded_stack[0][1]) >= max_depth:
            while bounded_stack and len(bounded_stack[0][1]) >= max_depth:
                bounded_stack.popleft()
            continue
        else:
            stack.append(bounded_stack.popleft())

    return []
