from collections import deque
import heapq

def solve(grid, start, goal):
    if (
        not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]))
        or not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0]))
        or grid[start[0]][start[1]] == '#'
        or grid[goal[0]][goal[1]] == '#'
    ):
        return []

    if start == goal:
        return [start]

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    queue = []
    heapq.heappush(queue, (manhattan(start, goal), 0, start, [start]))

    while queue:
        _, cost, current, path = heapq.heappop()
        if current == goal:
            return path
        if current in visited:
            continue
        visited.add(current)

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            next_row, next_col = current[0] + dr, current[1] + dc
            if (
                0 <= next_row < rows
                and 0 <= next_col < cols
                and grid[next_row][next_col] == '.'
                and (next_row, next_col) not in visited
            ):
                heapq.heappush(
                    queue,
                    (manhattan((next_row, next_col), goal), cost + 1, (next_row, next_col), path + [(next_row, next_col)])
                )

    return []
